beforeExample:
package test;

import com.ibm.icu.text.MessageFormat;

public class MyClass {
    public void someMethod() {
        String message = MessageFormat.format("Hello {0}", "World");
        System.out.println(message);
    }
}

afterExample:
package test;

import java.text.MessageFormat;

public class MyClass {
    public void someMethod() {
        String message = MessageFormat.format("Hello {0}", "World");
        System.out.println(message);
    }
}

negativeExample:
package test;

import java.text.MessageFormat; // Already using java.text.MessageFormat

public class MyClass {
    public void someMethod() {
        String message = MessageFormat.format("Hello {0}", "World"); // Should not be matched as it's already java.text
        System.out.println(message);
    }
}
